inline constexpr size_t CODE_FIXUP_COUNT = sizeof(CODE_FIXUPS)/sizeof(CODE_FIXUPS[0]);

// Byte offset of each runtime entry point / data slot within the blob.
struct Label { const char* name; uint32_t off; };
inline constexpr Label LABELS[] = {
    { "_start", 0xd50 },
    { "wandaa_append_file", 0x52a },
    { "wandaa_array_new", 0x97d },
    { "wandaa_bounds_trap", 0xbc0 },
    { "wandaa_crash_handler", 0x361 },
    { "wandaa_current_line", 0x10 },
    { "wandaa_empty_str", 0x40 },
    { "wandaa_init_stdout", 0x310 },
    { "wandaa_int_to_str", 0x86f },
    { "wandaa_misuse_trap", 0xc8e },
    { "wandaa_print_float", 0x9e0 },
    { "wandaa_print_int", 0x3a3 },
    { "wandaa_print_result", 0xce8 },
    { "wandaa_print_str", 0x330 },
    { "wandaa_print_strval", 0x43b },
    { "wandaa_read_file", 0x5bd },
    { "wandaa_result_trap", 0xc30 },
    { "wandaa_str_at", 0x7bf },
    { "wandaa_str_concat", 0x475 },
    { "wandaa_str_eq", 0x500 },
    { "wandaa_str_from_c", 0x73b },
    { "wandaa_str_len", 0x436 },
    { "wandaa_str_to_int", 0x929 },
    { "wandaa_substr", 0x7d6 },
    { "wandaa_write_file", 0x6a8 },
};
inline constexpr size_t LABEL_COUNT = sizeof(LABELS)/sizeof(LABELS[0]);

inline uint32_t labelOffset(const std::string& name) {
    for (size_t i = 0; i < LABEL_COUNT; ++i)
        if (name == LABELS[i].name) return LABELS[i].off;
    throw std::runtime_error("runtime blob has no label: " + name);
}
inline bool hasLabel(const std::string& name) {
    for (size_t i = 0; i < LABEL_COUNT; ++i)
        if (name == LABELS[i].name) return true;
    return false;
}

